import math

def pluck(arr):
    if not arr:
        return []

    min_even = float('inf')
    min_index = -1

    for i, num in enumerate(arr):
        if num % 2 == 0 and num < min_even:
            min_even = num
            min_index = i

    if min_even == float('inf'):
        return []

    return [min_even, min_index]
